import React, { useState, useEffect } from 'react';
import { useToast } from '../../contexts/ToastContext';
import { formatPrice } from '../../utils/priceCalculator';
import './PaymentModal.css';

const PaymentModal = ({ 
  isOpen, 
  onClose, 
  orderData, 
  selectedMethod: initialMethod = '',
  onPaymentSuccess,
  onPaymentError 
}) => {
  const { toast } = useToast();
  const [selectedMethod, setSelectedMethod] = useState(initialMethod);
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentStep, setPaymentStep] = useState('select');
  const [paymentType, setPaymentType] = useState('');

  const handlePayment = async () => {
    if (!selectedMethod || !orderData) {
      toast.error('결제 정보가 올바르지 않습니다.');
      return;
    }

    setIsProcessing(true);
    setPaymentStep('processing');

    try {
      if (selectedMethod === 'toss') {
        await handleTossPayment();
      } else if (selectedMethod === 'kakao') {
        await handleKakaoPayment();
      } else {
        throw new Error('지원하지 않는 결제 수단입니다.');
      }
    } catch (error) {
      console.error('결제 오류:', error);
      setPaymentStep('error');
      setIsProcessing(false);
      toast.error(`결제 중 오류가 발생했습니다: ${error.message}`);

      if (onPaymentError) {
        onPaymentError(error.message);
      }
    }
  };

  const handleTossPayment = async () => {
    try {
      // 토스페이먼츠 시뮬레이션
      await new Promise(resolve => setTimeout(resolve, 2000));

      setPaymentStep('success');
      setIsProcessing(false);

      const orderHistory = JSON.parse(localStorage.getItem('orderHistory') || '[]');
      const newOrder = {
        orderId: orderData.orderId || `TOSS_${Date.now()}`,
        items: orderData.items,
        totalAmount: orderData.totalAmount,
        paymentMethod: 'toss',
        paymentType: paymentType,
        paymentDate: new Date().toISOString(),
        status: 'completed',
      };
      orderHistory.unshift(newOrder);
      localStorage.setItem('orderHistory', JSON.stringify(orderHistory));

      toast.success('토스페이먼츠 결제가 완료되었습니다!');

      if (onPaymentSuccess) {
        onPaymentSuccess({ method: 'toss', orderId: orderData.orderId });
      }

    } catch (error) {
      throw new Error(`토스페이먼츠 결제 실패: ${error.message}`);
    }
  };

  const handleKakaoPayment = async () => {
    try {
      const apiUrl = 'http://localhost:8000/api/payments/kakao/prepare';
      const requestData = {
        cid: 'TC0ONETIME',
        partner_order_id: orderData.orderId || `KAKAO_${Date.now()}`,
        partner_user_id: orderData.userInfo?.id || 'user_001',
        item_name: `커비 상품 주문 (${orderData.items?.length || 1}개)`,
        quantity: 1,
        total_amount: orderData.totalAmount || 1000,
        tax_free_amount: 0,
        approval_url: `${window.location.origin}/payment/success`,
        cancel_url: `${window.location.origin}/payment/cancel`,
        fail_url: `${window.location.origin}/payment/fail`
      };

      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer test-token'
        },
        body: JSON.stringify(requestData)
      });

      if (!response.ok) {
        throw new Error(`API 요청 실패: ${response.status}`);
      }

      const result = await response.json();

      if (!result.success) {
        throw new Error(result.message || result.error || '카카오페이 결제 준비에 실패했습니다.');
      }

      window.open(result.next_redirect_pc_url, 'kakao_payment', 'width=1000,height=800');

      setPaymentStep('success');
      setIsProcessing(false);

      const orderHistory = JSON.parse(localStorage.getItem('orderHistory') || '[]');
      const newOrder = {
        orderId: orderData.orderId || `KAKAO_${Date.now()}`,
        items: orderData.items,
        totalAmount: orderData.totalAmount,
        paymentMethod: 'kakao',
        paymentDate: new Date().toISOString(),
        status: 'completed',
      };
      orderHistory.unshift(newOrder);
      localStorage.setItem('orderHistory', JSON.stringify(orderHistory));

      toast.success('카카오페이 결제가 완료되었습니다!');

      if (onPaymentSuccess) {
        onPaymentSuccess({ method: 'kakao', orderId: orderData.orderId });
      }

    } catch (error) {
      throw new Error(`카카오페이 결제 실패: ${error.message}`);
    }
  };

  const handleMethodSelect = (method) => {
    if (isProcessing) return;
    setSelectedMethod(method);
    setPaymentStep('select');
  };

  const handleClose = () => {
    if (isProcessing) return;
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="payment-modal-overlay">
      <div className="payment-modal">
        <div className="payment-modal-header">
          <h2>결제하기</h2>
          <button className="close-btn" onClick={handleClose}>×</button>
        </div>

        <div className="payment-content">
          {paymentStep === 'select' && (
            <>
              <div className="payment-summary">
                <h3>결제 요약</h3>
                <div className="summary-item">
                  <span>상품 금액:</span>
                  <span>{formatPrice(orderData?.totalAmount || 0)}</span>
                </div>
                <div className="summary-item">
                  <span>배송비:</span>
                  <span>{formatPrice(orderData?.shippingFee || 0)}</span>
                </div>
                <div className="summary-item total">
                  <span>총 결제 금액:</span>
                  <span>{formatPrice(orderData?.totalAmount || 0)}</span>
                </div>
              </div>

              <div className="payment-methods">
                <h3>결제 수단 선택</h3>
                <div className="method-options">
                  <button 
                    className={`method-btn ${selectedMethod === 'toss' ? 'active' : ''}`}
                    onClick={() => handleMethodSelect('toss')}
                    disabled={isProcessing}
                  >
                    <div className="method-icon toss">T</div>
                    <div className="method-info">
                      <div className="method-name">토스페이먼츠</div>
                      <div className="method-desc">간편하고 안전한 결제</div>
                    </div>
                  </button>

                  <button 
                    className={`method-btn ${selectedMethod === 'kakao' ? 'active' : ''}`}
                    onClick={() => handleMethodSelect('kakao')}
                    disabled={isProcessing}
                  >
                    <div className="method-icon kakao">K</div>
                    <div className="method-info">
                      <div className="method-name">카카오페이</div>
                      <div className="method-desc">카카오톡으로 간편 결제</div>
                    </div>
                  </button>
                </div>
              </div>

              {selectedMethod === 'toss' && (
                <div className="toss-payment-container">
                  <h3>토스페이먼츠 결제</h3>

                  {/* 멋진 블랙 카드 */}
                  <div className="toss-card">
                    <div className="toss-card-header">
                      <div className="toss-logo">TOSS</div>
                      <div className="toss-chip"></div>
                    </div>
                    <div className="toss-card-number">4532 •••• •••• 1234</div>
                    <div className="toss-card-info">
                      <div className="toss-card-holder">KIRBY SHOP</div>
                      <div className="toss-card-expiry">12/25</div>
                    </div>
                    <div className="toss-card-brand">VISA</div>
                  </div>                  <div className="payment-types">
                    <button 
                      className={`payment-type-btn ${paymentType === 'card' ? 'active' : ''}`}
                      onClick={() => setPaymentType('card')}
                    >
                      💳 신용카드
                    </button>
                    <button 
                      className={`payment-type-btn ${paymentType === 'bank' ? 'active' : ''}`}
                      onClick={() => setPaymentType('bank')}
                    >
                      🏦 계좌이체
                    </button>
                    <button 
                      className={`payment-type-btn ${paymentType === 'easy' ? 'active' : ''}`}
                      onClick={() => setPaymentType('easy')}
                    >
                      📱 간편결제
                    </button>
                    <button 
                      className={`payment-type-btn ${paymentType === 'convenience' ? 'active' : ''}`}
                      onClick={() => setPaymentType('convenience')}
                    >
                      🏪 편의점
                    </button>
                  </div>
                  <button 
                    className="payment-btn"
                    onClick={handlePayment}
                    disabled={isProcessing || !paymentType}
                  >
                    {isProcessing ? '결제 처리 중...' : `${paymentType ? '결제하기' : '결제 수단을 선택하세요'}`}
                  </button>
                </div>
              )}

              {selectedMethod === 'kakao' && (
                <div className="kakao-payment-container">
                  <h3>카카오페이 결제</h3>
                  <button 
                    className="payment-btn kakao"
                    onClick={handlePayment}
                    disabled={isProcessing}
                  >
                    {isProcessing ? '결제 처리 중...' : '카카오페이로 결제하기'}
                  </button>
                </div>
              )}
            </>
          )}

          {paymentStep === 'processing' && (
            <div className="processing-state">
              <div className="loading-spinner"></div>
              <h3>결제 처리 중...</h3>
              <p>잠시만 기다려주세요.</p>
            </div>
          )}

          {paymentStep === 'success' && (
            <div className="success-state">
              <div className="success-icon">✅</div>
              <h3>결제 완료!</h3>
              <p>결제가 성공적으로 완료되었습니다.</p>
              <button className="success-btn" onClick={() => window.location.href = '/order-history'}>
                주문 내역 보기
              </button>
            </div>
          )}

          {paymentStep === 'error' && (
            <div className="error-state">
              <div className="error-icon">❌</div>
              <h3>결제 실패</h3>
              <p>결제 중 오류가 발생했습니다.</p>
              <button className="retry-btn" onClick={() => setPaymentStep('select')}>
                다시 시도
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PaymentModal;
